fn netif_tx_wake_all_queues(dev: *mut net_device) {
let mut i: u32 = 0;
while i < unsafe { (*dev).num_tx_queues } {
let txq: *mut netdev_queue = netdev_get_tx_queue(dev as *const net_device, i);
unsafe { netif_tx_wake_queue(txq) };
i = i.wrapping_add(1);
}
}

#[inline(always)]
