fn ethtool_validate_speed(speed: u32) -> i32 {
(speed <= 2147483647u32 || speed == (1i32.wrapping_neg() as u32)) as i32
}

// Duplex, half or full.
fn ethtool_validate_duplex(duplex: u8) -> i32 {
match duplex as i32 {
0 | 1 | 255 => {
return 1;
}
_ => {
}
}
0
}

